    Headers = Table.PromoteHeaders(Source, [PromoteAllScalars=true]),
    Typed = Table.TransformColumnTypes(Headers, {{"CustomerID", type text}, {"CustomerName", type text}, {"City", type text}}, "en-US"),
    Trimmed = Table.TransformColumns(Typed, {{"CustomerID", Text.Trim, type text}, {"CustomerName", Text.Trim, type text}, {"City", Text.Trim, type text}})
in
    Trimmed

