// SourceWarehouses
let
    Source = Csv.Document(Binary.FromText("V2FyZWhvdXNlSUQsTG9jYXRpb24KVzAxLEFidWphClcwMixBYnVqYQpXMDMsQWJ1amEKVzA0LExhZ29zClcwNSxMYWdvcwpXMDYsTGFnb3MKVzA3LExhZ29zClcwOCxLYW5vClcwOSxMYWdvcwpXMTAsS2FubwpXMTEsTGFnb3MKVzEyLEFidWphClcxMyxMYWdvcwpXMTQsTGFnb3MKVzE1LEthbm8K", BinaryEncoding.Base64), [Delimiter=",", Encoding=65001, QuoteStyle=QuoteStyle.Csv]),
